async def act(page):
    import asyncio
    import csv
    import os
    import re

    # Reasoning about KB functions:
    # - export_customers_csv_via_grid: This helper exports the Customers management grid as CSV.
    #   It is not useful for counting canceled orders because the Customers CSV does not contain
    #   per-order status data that indicates cancellations. Therefore we will NOT call it.

    # Plan:
    # 1) Navigate to the Orders admin grid to ensure a deterministic starting point.
    # 2) Trigger the standard orders CSV export endpoint and capture the download.
    #    If that fails, attempt a best-effort Export button click as a fallback.
    # 3) Parse the downloaded CSV robustly, guarding against None values when calling .strip().
    # 4) Count orders whose status indicates cancellation per-customer and print the maximum count.

    # Navigate to orders grid (relative goto)
    await page.goto('/index.php/admin/sales_order/')
    await asyncio.sleep(1)

    download_path = 'orders.csv'
    try:
        if os.path.exists(download_path):
            os.remove(download_path)
    except Exception:
        pass

    # Attempt to download via the common exportCsv endpoint
    try:
        with page.expect_download() as download_info:
            # This navigation typically triggers an immediate CSV download in Magento
            await page.goto('/index.php/admin/sales_order/exportCsv/')
        download = await download_info.value
        await download.save_as(download_path)
    except Exception:
        # Fallback: try to click an Export button on the page (best-effort)
        try:
            export_buttons = page.get_by_role('button', name=re.compile(r"export", re.I))
            if await export_buttons.count() > 0:
                with page.expect_download() as download_info:
                    await export_buttons.first.click()
                download = await download_info.value
                await download.save_as(download_path)
            else:
                raise RuntimeError('No export button found to trigger CSV download')
        except Exception as e:
            raise RuntimeError(f'Failed to download orders CSV: {e}')

    # Parse CSV and count cancelled orders per customer
    counts = {}
    try:
        with open(download_path, newline='', encoding='utf-8', errors='replace') as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames or []

            # Identify likely status field
            status_field = None
            for h in headers:
                if h and 'status' in h.lower():
                    status_field = h
                    break

            # Identify combined name field preference
            combined_name_field = None
            for h in headers:
                if not h:
                    continue
                low = h.lower()
                # prefer billing or customer combined name fields
                if 'billing_name' in low or 'billing name' in low or 'customer_name' in low or 'customer name' in low or low == 'name':
                    combined_name_field = h
                    break

            # Identify firstname/lastname/email fallbacks
            firstname_field = None
            lastname_field = None
            email_field = None
            for h in headers:
                if not h:
                    continue
                low = h.lower()
                if ('first' in low and ('name' in low or 'firstname' in low)) or low.endswith('firstname'):
                    firstname_field = h
                if ('last' in low and ('name' in low or 'lastname' in low)) or low.endswith('lastname'):
                    lastname_field = h
                if 'email' in low and email_field is None:
                    email_field = h

            for row in reader:
                # Safely fetch status value
                status_val = ''
                if status_field:
                    status_val = (row.get(status_field) or '')
                else:
                    # fallback: join visible fields to search for 'cancel'
                    status_val = ' '.join((row.get(h) or '') for h in headers)

                if 'cancel' not in status_val.lower():
                    continue

                # Build a customer identifier safely (avoid calling .strip() on None)
                customer = None
                if combined_name_field and (row.get(combined_name_field) or '').strip():
                    customer = (row.get(combined_name_field) or '').strip()
                else:
                    first = (row.get(firstname_field) or '').strip() if firstname_field else ''
                    last = (row.get(lastname_field) or '').strip() if lastname_field else ''
                    if first or last:
                        customer = (first + ' ' + last).strip()
                    elif email_field and (row.get(email_field) or '').strip():
                        customer = (row.get(email_field) or '').strip()
                    else:
                        # fallback: pick first non-empty cell value as a surrogate id
                        for h in headers:
                            v = (row.get(h) or '').strip()
                            if v:
                                customer = v
                                break
                        if not customer:
                            customer = '__unknown__'

                counts[customer] = counts.get(customer, 0) + 1
    except FileNotFoundError:
        raise RuntimeError('Downloaded CSV file not found')

    max_count = max(counts.values()) if counts else 0

    # Print result for harness capture and return
    print(max_count)
    return max_count

